<!doctype html>
<html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Persetujuan Dispensasi Siswa</title><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#eef2f7;margin:0;padding:20px;color:#1e293b}.box{max-width:620px;margin:auto;background:#fff;padding:26px;border-radius:14px;box-shadow:0 8px 24px #0f172a1f}h1{font-size:22px}.intro{font-size:13px;color:#64748b;line-height:1.5}.info{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px}.row{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid #e2e8f0;font-size:13px}.row:last-child{border:0}.label{color:#64748b}.status{padding:6px 9px;border-radius:6px;background:#fef3c7;color:#92400e;font-weight:700;font-size:12px}.ok{background:#dcfce7;color:#166534}.no{background:#fee2e2;color:#991b1b}.decision{border-top:1px solid #e2e8f0;margin-top:20px;padding-top:18px}textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;resize:vertical;margin:8px 0 10px}button{border:0;border-radius:8px;padding:11px 15px;color:#fff;font-weight:700;cursor:pointer}.yes{background:#16a34a}.reject{background:#dc2626;margin-left:6px}@media(max-width:520px){body{padding:10px}.box{padding:20px}.row{display:block}.row strong,.row .status{display:block;margin-top:4px}.reject{margin-left:4px}}</style></head><body><main class="box"><h1>Persetujuan Dispensasi Siswa</h1><p class="intro">Halaman khusus {{ $role === 'waka' ? 'Waka' : 'Guru Piket' }}. Tidak perlu login.</p><section class="info"><div class="row"><span class="label">Siswa</span><strong>{{ $dispen->siswa->nama_siswa ?? '-' }}</strong></div><div class="row"><span class="label">Kelas</span><strong>{{ $dispen->siswa->kelas->nama_kelas ?? '-' }}</strong></div><div class="row"><span class="label">Tanggal</span><strong>{{ $dispen->tanggal_dispen->format('d-m-Y') }}</strong></div><div class="row"><span class="label">Alasan</span><strong>{{ $dispen->alasan }}</strong></div></section><div class="decision"><h2>Keputusan {{ $role === 'waka' ? 'Waka' : 'Guru Piket' }}</h2><div class="row"><span class="label">Status</span><span class="status {{ $status === 'disetujui' ? 'ok' : ($status === 'ditolak' ? 'no' : '') }}">{{ ucfirst($status) }}</span></div>@if(session('approval_message'))<p style="color:#166534;font-weight:700">{{ session('approval_message') }}</p>@endif @if($status === 'menunggu')<form method="POST" action="{{ $approvalUrl }}" onsubmit="return konfirmasi(event, '{{ $role === 'waka' ? 'Waka' : 'Guru Piket' }}')">@csrf<textarea name="catatan" rows="3" placeholder="Catatan (opsional)"></textarea><button class="yes" name="keputusan" value="disetujui">Setujui Dispensasi</button><button class="reject" name="keputusan" value="ditolak">Tolak Dispensasi</button></form>@else<p class="intro">Keputusan sudah diberikan.</p>@endif</div></main><script>function konfirmasi(e,role){e.preventDefault();const form=e.target,isReject=e.submitter&&e.submitter.value==='ditolak';Swal.fire({title:isReject?'Tolak dispensasi?':'Setujui dispensasi?',text:'Keputusan sebagai '+role+' akan disimpan.',icon:isReject?'warning':'question',showCancelButton:true,confirmButtonText:isReject?'Ya, tolak':'Ya, setujui',cancelButtonText:'Batal',confirmButtonColor:isReject?'#dc2626':'#16a34a',cancelButtonColor:'#64748b',reverseButtons:true}).then(r=>{if(r.isConfirmed){const i=document.createElement('input');i.type='hidden';i.name='keputusan';i.value=isReject?'ditolak':'disetujui';form.appendChild(i);form.submit()}})}</script></body></html>
